import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { ShipmentItem } from '../../src/entities/shipment-item.entity';
import { buildShipmentItem } from '../factories/shipment-item.factory';
import { Shipment } from '../../src/entities/shipment.entity';
import { buildShipment } from '../factories/shipment.factory';

describe('ShipmentItem Repository', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let shipmentId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const shipmentEntity = em.create(
      Shipment,
      buildShipment(),
    );
    await em.persistAndFlush(shipmentEntity);
    shipmentId = shipmentEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  it('creates and persists an entity', async () => {
    const em = orm.em.fork();
    const data = buildShipmentItem({ shipment: shipmentId });
    const entity = em.create(ShipmentItem, data);
    await em.persistAndFlush(entity);
    expect(entity.id).toBeDefined();
  });

  it('retrieves an entity by id', async () => {
    const em = orm.em.fork();
    const data = buildShipmentItem({ shipment: shipmentId });
    const saved = em.create(ShipmentItem, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(ShipmentItem, { id: saved.id });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('returns null for non-existent id', async () => {
    const em = orm.em.fork();
    const found = await em.findOne(ShipmentItem, {
      id: '00000000-0000-0000-0000-000000000099',
    });
    expect(found).toBeNull();
  });

  it('updates an entity field', async () => {
    const em = orm.em.fork();
    const data = buildShipmentItem({ shipment: shipmentId });
    const saved = em.create(ShipmentItem, data);
    await em.persistAndFlush(saved);
    saved.productId = '660e8400-e29b-41d4-a716-446655440001';
    await em.flush();
    const reloaded = await em.findOne(ShipmentItem, { id: saved.id });
    expect(reloaded).not.toBeNull();
    expect(reloaded!.productId).toEqual(saved.productId);
  });

  it('deletes an entity', async () => {
    const em = orm.em.fork();
    const data = buildShipmentItem({ shipment: shipmentId });
    const saved = em.create(ShipmentItem, data);
    await em.persistAndFlush(saved);
    await em.removeAndFlush(saved);
    const found = await em.findOne(ShipmentItem, { id: saved.id });
    expect(found).toBeNull();
  });

  it('lists all entities', async () => {
    const em = orm.em.fork();
    const data = buildShipmentItem({ shipment: shipmentId });
    await em.persistAndFlush(em.create(ShipmentItem, data));
    const all = await em.find(ShipmentItem, {});
    expect(all.length).toBeGreaterThanOrEqual(1);
  });

  it('persists with shipment foreign key', async () => {
    const em = orm.em.fork();
    const data = buildShipmentItem({ shipment: shipmentId });
    const saved = em.create(ShipmentItem, data);
    await em.persistAndFlush(saved);
    await em.populate(saved, ['shipment']);
    expect(saved.shipment.id).toBe(shipmentId);
  });
});
